// 4901 = Chain Disconnected analog for unsupported networks.
function canonicalizeBtcNetworkId(
  networkId: string,
): IDeriveContextHashKeyringParams['canonicalNetworkName'] {
  switch (networkId) {
    case 'btc--0':
      return 'bitcoin-mainnet';
    case 'tbtc--0':
      return 'bitcoin-testnet';
    case 'tbtc--1':
      return 'bitcoin-signet';
    default:
      throw web3Errors.provider.custom({
        code: 4901,
        message: `deriveContextHash is not supported on this network: ${networkId}`,
      });
  }
}

function getQueryDAppAccountParams(params: IGetDAppAccountInfoParams) {
  const { scope, isWalletConnectRequest, options = {} } = params;

  const storageType: IConnectionStorageType = isWalletConnectRequest
    ? 'walletConnect'
    : 'injectedProvider';
  let networkImpls: string[] | undefined = [];
  if (options.networkImpl) {
    networkImpls = [options.networkImpl];
  } else if (scope) {
    networkImpls = getNetworkImplsFromDappScope(scope);
  }

  if (!networkImpls) {
    throw new OneKeyLocalError('networkImpl not found');
  }
  return {
    storageType,
    networkImpls,
  };
}

