  @backgroundMethod()
  public async openModal({
    request,
    screens = [],
    params = {},
    fullScreen,
  }: {
    request: IJsBridgeMessagePayload;
    screens: any[];
    params?: any;
    fullScreen?: boolean;
  }) {
    defaultLogger.discovery.dapp.dappOpenModal({
      request,
      screens,
      params,
    });
    // Try to open an existing window anyway in the extension
    this.tryOpenExistingExtensionWindow({ origin: request.origin });

    return this.semaphore.runExclusive(async () => {
      try {
        return await new Promise((resolve, reject) => {
          if (!request.origin) {
            throw new OneKeyLocalError('origin is required');
          }
          if (!request.scope) {
            throw new OneKeyLocalError('scope is required');
          }
          const id = this.backgroundApi.servicePromise.createCallback({
            resolve,
            reject,
          });
          const modalScreens = screens;
          const routeNames = [
            fullScreen ? ERootRoutes.iOSFullScreen : ERootRoutes.Modal,
            ...modalScreens,
          ];
          // WalletConnectRequestProxy stuffs the SDK's verifyContext into
          // request.data so that no extra plumbing through each chain
          // provider is needed; hoist it back out so the modal sees it as a
          // first-class field instead of digging through the RPC data.
          const walletConnectVerifyContext = (
            request.data as
              | { walletConnectVerifyContext?: Verify.Context }
              | undefined
          )?.walletConnectVerifyContext;
          const $sourceInfo: IDappSourceInfo = {
            id,
            origin: request.origin,
            hostname: uriUtils.getHostNameFromUrl({ url: request.origin }),
            scope: request.scope,
            data: request.data as any,
            isWalletConnectRequest: !!request.isWalletConnectRequest,
            walletConnectVerifyContext,
          };

          this.existingWindowOrigin = request.origin;

          const routeParams = {
            // stringify required, nested object not working with Ext route linking
            query: JSON.stringify(
              {
                $sourceInfo,
                ...params,
                _$t: Date.now(),
              },
              (key, value) =>
                // eslint-disable-next-line @typescript-eslint/no-unsafe-return
                typeof value === 'bigint' ? value.toString() : value,
            ),
          };

          const modalParams = buildModalRouteParams({
            screens: routeNames,
            routeParams,
          });

          ensureSerializable(modalParams);

          void this._openModalByRouteParamsDebounced({
            routeNames,
            routeParams,
            modalParams,
            // Without this the request can never settle when the push itself
            // fails (chrome.windows.create rejected, or openSidePanel throwing
            // because the panel closed inside the debounce window). The
            // debounced call returns undefined to this caller and invokes on a
            // later timer, so its rejection is unreachable from here — the
            // callback has to be handed down. Left unsettled, `finally` never
            // runs and existingWindowOrigin stays set, which now also gates
            // user-visible update UI.
            //
            // Goes through servicePromise rather than the raw `reject` so the
            // registration is removed too; rejecting the promise directly would
            // settle the caller but leave the entry dangling until the
            // 30-minute expiry sweep re-rejects an already-settled promise.
            onError: (error) => {
              void this.backgroundApi.servicePromise.rejectCallback({
                id,
                error,
              });
            },
          });
        });
      } finally {
        this.existingWindowId = null;
        this.existingWindowOrigin = null;
      }
    });
  }

  _openModalByRouteParams = async ({
    modalParams,
    routeParams,
    routeNames,
    onError,
  }: {
    routeNames: any[];
    routeParams: { query: string };
    modalParams: { screen: any; params: any };
    onError?: (error: unknown) => void;
  }) => {
    try {
      await this._doOpenModalByRouteParams({
        modalParams,
        routeParams,
        routeNames,
      });
    } catch (error) {
      // Surface the failure to the waiting request instead of leaving it (and
      // the pending-approval bookkeeping) hanging until the 30-minute sweep.
      if (onError) {
        onError(error);
        return;
      }
      throw error;
    }
  };

  _doOpenModalByRouteParams = async ({
    modalParams,
    routeParams,
    routeNames,
  }: {
    routeNames: any[];
    routeParams: { query: string };
    modalParams: { screen: any; params: any };
  }) => {
    if (platformEnv.isExtension) {
      if (sidePanelState.isOpen || platformEnv.isExtensionUiSidePanel) {
        await extUtils.openSidePanel({
          routes: routeNames,
          params: routeParams,
          modalParams,
        });
      } else {
        // check packages/kit/src/routes/config/getStateFromPath.ext.ts for Ext hash route
        const extensionWindow = await extUtils.openStandaloneWindow({
          routes: routeNames,
          params: routeParams,
        });
        this.existingWindowId = extensionWindow.id;
      }
    } else if (appGlobals.$navigationRef?.current) {
      if (
        platformEnv.isNative &&
        (routeNames[0] === ERootRoutes.Modal ||
          routeNames[0] === ERootRoutes.iOSFullScreen) &&
        routeNames[1] === EModalRoutes.DAppConnectionModal &&
        routeNames[2] === EDAppConnectionModal.WalletConnectSessionProposalModal
      ) {
        // Progress dismissal is best-effort. A ready navigation ref must not
        // depend on the background relay's React effect having mounted.
        void Promise.resolve()
          .then(() =>
            appEventBus.emit(
              EAppEventBusNames.WalletConnectCloseConnectionProgress,
              undefined,
            ),
          )
          .catch(() => undefined);
      }
      const doOpenModal = () =>
        appGlobals.$navigationRef.current?.navigate(
          modalParams.screen,
          modalParams.params,
        );
      console.log('modalParams: ', modalParams);
      // TODO remove timeout after dapp request queue implemented.
      doOpenModal();
    } else {
      // Relay to the main runtime when navigation belongs to another JS heap.
      appEventBus.emit(EAppEventBusNames.NavigateModalFromBackgroundThread, {
        screen: modalParams.screen,
        params: modalParams.params,
      });
    }
  };

  _openModalByRouteParamsDebounced = debounce(
    this._openModalByRouteParams,
    800,
    {
      leading: false,
      trailing: true,
    },
  );

  // True from the moment a DApp approval is queued — set before the debounced
  // modal push and cleared when the request settles — so it already reads true
  // in the window before the modal actually appears.
  @backgroundMethod()
  async hasPendingDappRequest(): Promise<boolean> {
    return !!this.existingWindowOrigin;
  }

  // Public so provider APIs that queue connect requests on their own
  // semaphore (e.g. eth_requestAccounts) can surface the pending approval
  // window before the queued call ever reaches openModal. Focusing requires
  // the caller's origin to own the pending window — surfacing DApp A's
  // approval window on DApp B's connect click invites approving the wrong
  // origin; cross-origin requests just stay queued until their own modal
  // window is created.
  tryOpenExistingExtensionWindow({ origin }: { origin?: string | null } = {}) {
    if (
      platformEnv.isExtension &&
      this.existingWindowId &&
      origin &&
      origin === this.existingWindowOrigin
    ) {
      extUtils.focusExistWindow({ windowId: this.existingWindowId });
    }
  }

